sql.where:
t.deleted = 0

    AND t.task_no = #{req.taskNo}


    AND t.qc_plan_version = #{req.qcPlanVersion}


    AND t.trigger_point = #{req.triggerPoint}


    AND t.biz_type = #{req.bizType}


    AND t.biz_no = #{req.bizNo}


    AND t.biz_line_id = #{req.bizLineId}


    AND t.mat_id = #{req.matId}


    AND t.mat_code = #{req.matCode}


    AND t.mat_name LIKE CONCAT('%', #{req.matName}, '%')


    AND t.mat_spec = #{req.matSpec}


    AND t.batch_id = #{req.batchId}


    AND t.lot_no = #{req.lotNo}


    AND t.qty = #{req.qty}


    AND t.sample_qty = #{req.sampleQty}


    AND t.uom_id = #{req.uomId}


    AND t.uom_code = #{req.uomCode}


    AND t.assigned_inspector_id = #{req.assignedInspectorId}


    AND t.inspect_start_time = #{req.inspectStartTime}


    AND t.inspect_end_time = #{req.inspectEndTime}


    AND t.conclusion = #{req.conclusion}


    AND t.qty_qualified = #{req.qtyQualified}


    AND t.qty_rejected = #{req.qtyRejected}


    AND t.status = #{req.status}


    AND t.idempotency_key = #{req.idempotencyKey}


    AND t.version = #{req.version}


    AND t.remark = #{req.remark}


    AND t.create_time = #{req.createTime}
